panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:56px 60px 0;background:radial-gradient(circle at 10% 20%,rgba(214,62,118,.12),transparent 45%),radial-gradient(circle at 92% 80%,rgba(245,197,24,.16),transparent 48%),var(--cream)}
.k{font-size:30px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:58px;font-weight:900;line-height:1.25;text-align:center;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.note{position:absolute;left:60px;right:60px;bottom:40px;font-size:23px}
.list{display:flex;flex-direction:column;gap:16px;margin-top:38px}
.r{display:flex;gap:24px;align-items:center;background:#fff;border-radius:24px;padding:20px 28px;box-shadow:0 14px 30px -24px rgba(30,18,25,.45);border-left:14px solid #F5C518}
.r.flip{border-left-color:#D63E76}
.gb{flex:0 0 170px;font-size:32px;font-weight:900;color:#fff;background:#46293A;border-radius:16px;text-align:center;padding:10px 0}
.tx{flex:1}.tx b{display:block;font-size:34px;font-weight:900;height:46px;line-height:46px}.tx b img{height:42px;vertical-align:middle;object-fit:contain}
.tx span{display:block;font-size:22px;color:var(--ink-2)}
.yen{font-size:48px;font-weight:900;color:#D63E76;white-space:nowrap}.yen small{font-size:26px}
.one{margin-top:28px;text-align:center;font-size:30px;font-weight:700;background:#46293A;color:#fff;border-radius:18px;padding:18px 16px}.one b{color:#F5C518;font-weight:900}
